description:
Implement `asyncBatch(items, batchSize, process)` that splits `items` into groups of `batchSize` and calls `process(batch)` for each group sequentially, awaiting each before starting the next.

**Example:**
```js
await asyncBatch([1,2,3,4,5], 2, async (batch) => {
  await saveToDb(batch); // called with [1,2], then [3,4], then [5]
});
```

starter_code:
export async function asyncBatch(items, batchSize, process) {
  // your code here
}

test_suite:
test('calls process with groups of batchSize', async () => {
  const batches = [];
  await asyncBatch([1, 2, 3, 4], 2, async (batch) => { batches.push(batch); });
  expect(batches).toEqual([[1, 2], [3, 4]]);
});

test('last batch can be smaller', async () => {
  const batches = [];
  await asyncBatch([1, 2, 3], 2, async (batch) => { batches.push(batch); });
  expect(batches).toEqual([[1, 2], [3]]);
});

test('processes batches sequentially', async () => {
  const order = [];
  await asyncBatch([1, 2, 3], 1, async (batch) => {
    order.push(batch[0]);
  });
  expect(order).toEqual([1, 2, 3]);
});

// __hidden__
test('empty items array calls process zero times', async () => {
  const process = vi.fn();
  await asyncBatch([], 2, process);
  expect(process).not.toHaveBeenCalled();
});

solution:
export async function asyncBatch(items, batchSize, process) {
  for (let i = 0; i < items.length; i += batchSize) {
    await process(items.slice(i, i + batchSize));
  }
}
